-- ============================================================
-- MIGRATION: Add customer_number and order_number
-- ============================================================

-- 1. Tambah customer_number ke customer_profiles (GENERATED BY DEFAULT agar bisa backfill)
ALTER TABLE customer_profiles ADD COLUMN customer_number INTEGER GENERATED BY DEFAULT AS IDENTITY (START WITH 1001 INCREMENT BY 1);

-- 2. Tambah order_number ke orders (GENERATED BY DEFAULT agar bisa backfill)
ALTER TABLE orders ADD COLUMN order_number INTEGER GENERATED BY DEFAULT AS IDENTITY (START WITH 1001 INCREMENT BY 1);

-- 3. Tambah indexes untuk performa
CREATE INDEX IF NOT EXISTS idx_customer_profiles_customer_number ON customer_profiles(customer_number);
CREATE INDEX IF NOT EXISTS idx_orders_order_number ON orders(order_number);

-- 4. Backfill customer_number untuk data existing (set manual, mulai dari 1)
UPDATE customer_profiles SET customer_number = subquery.rn FROM (
  SELECT id, ROW_NUMBER() OVER (ORDER BY created_at) as rn FROM customer_profiles
) AS subquery WHERE customer_profiles.id = subquery.id;

-- 5. Backfill order_number untuk data existing (set manual, mulai dari 1)
UPDATE orders SET order_number = subquery.rn FROM (
  SELECT id, ROW_NUMBER() OVER (ORDER BY created_at) as rn FROM orders
) AS subquery WHERE orders.id = subquery.id;

-- 6. Reset sequence agar start dari max value + 1
SELECT setval(pg_get_serial_sequence('customer_profiles', 'customer_number'), COALESCE((SELECT MAX(customer_number) FROM customer_profiles), 0) + 1, true);
SELECT setval(pg_get_serial_sequence('orders', 'order_number'), COALESCE((SELECT MAX(order_number) FROM orders), 0) + 1, true);